/**
 * Sprite registry. Every *.ts file in this folder that exports
 * `sprites: SpriteDef[]` and/or `fonts: FontDef[]` is picked up automatically.
 * Do not edit this file to register new art - just add a file.
 */
import type { FontDef, SpriteDef } from "../format";

type Mod = { sprites?: SpriteDef[]; fonts?: FontDef[] };
const mods = import.meta.glob<Mod>("./*.ts", { eager: true });

export const ALL_SPRITES: SpriteDef[] = [];
export const ALL_FONTS: FontDef[] = [];
/** id -> source file (for diagnostics) */
export const SPRITE_SOURCE = new Map<string, string>();

for (const [path, mod] of Object.entries(mods)) {
  if (path.endsWith("/index.ts")) continue;
  for (const s of mod.sprites ?? []) {
    if (SPRITE_SOURCE.has(s.id)) {
      console.warn(`[art] duplicate sprite id '${s.id}' in ${path} (already in ${SPRITE_SOURCE.get(s.id)})`);
      continue;
    }
    SPRITE_SOURCE.set(s.id, path);
    ALL_SPRITES.push(s);
  }
  for (const f of mod.fonts ?? []) ALL_FONTS.push(f);
}
